// 1. Fetch existing session data from the database lookup
const sessionRow = $items("MSSQL: Get Session")[0]?.json?.cart_json;
let currentCart = sessionRow ? (typeof sessionRow === 'string' ? JSON.parse(sessionRow) : sessionRow) : [];

// 2. Safely capture the incoming LLM data
let parsedLLM = {};
if ($json.output) {
  parsedLLM = $json.output;
} else if ($json.text) {
  let cleanText = $json.text.replace(/```json/g, '').replace(/```/g, '').trim();
  try { parsedLLM = JSON.parse(cleanText); } catch(e) { parsedLLM = $json; }
} else {
  parsedLLM = $json;
}

// DEFENSIVE CHECK: Default cleanly if the model hallucinated
if (!parsedLLM || typeof parsedLLM !== 'object' || Array.isArray(parsedLLM)) {
  parsedLLM = { customer_message: "🤖 To complete your order, just reply with 'YES'. To modify items, tell me what you would like to add or remove!", ordered_items: [], ready_for_checkout: false };
}

// 3. ✨ THE FIX: Deterministic Intent Override ✨
const triggerItem = $items("Telegram Trigger")[0].json.message;
const incomingText = triggerItem.text ? triggerItem.text.toLowerCase().trim() : "";
const chatId = triggerItem.chat.id;

// Force the checkout flag to TRUE if the user explicitly typed "yes"
let forceCheckout = parsedLLM.ready_for_checkout === true || parsedLLM.ready_for_checkout === "true";
if (incomingText === 'yes') {
    forceCheckout = true;
}

// 4. Reconcile cart state line items safely (Only if we are NOT checking out)
if (!forceCheckout) {
    const incomingUpdates = Array.isArray(parsedLLM.ordered_items) ? parsedLLM.ordered_items : [];

    incomingUpdates.forEach(newItem => {
      if (!newItem || !newItem.item_name) return; // Skip empty objects

      const targetName = newItem.item_name.toLowerCase().trim();
      const targetSize = newItem.size ? newItem.size.toLowerCase().trim() : 'n/a';

      const matchIndex = currentCart.findIndex(cartItem => 
        cartItem.item_name.toLowerCase().trim() === targetName && 
        (cartItem.size ? cartItem.size.toLowerCase().trim() : 'n/a') === targetSize
      );

      if (matchIndex > -1) {
        if (newItem.quantity <= 0) {
          currentCart.splice(matchIndex, 1);
        } else {
          currentCart[matchIndex].quantity = newItem.quantity;
          currentCart[matchIndex].special_instructions = newItem.special_instructions || 'none';
        }
      } else if (newItem.quantity > 0) {
        currentCart.push({
          item_name: newItem.item_name,
          size: newItem.size || 'Medium',
          quantity: newItem.quantity,
          special_instructions: newItem.special_instructions || 'none'
        });
      }
    });
}

// 5. Pre-serialize and escape data for safe database integration
const safeCartString = JSON.stringify(currentCart).replace(/'/g, "''");

return {
  json: {
    chat_id: chatId,
    updated_cart: currentCart,
    cart_json_string: safeCartString,
    ready_for_checkout: forceCheckout,
    customer_message: parsedLLM.customer_message || "🤖 I didn't quite catch that. To complete your order, just reply with 'YES'."
  }
};

