SET XACT_ABORT ON; -- Forces SQL Server to roll back instantly on errors and reveal the real issue

BEGIN TRANSACTION;

BEGIN TRY
    DECLARE @NewOrderId INT;

    -- 1. Insert parent order
    INSERT INTO orders (chat_id, order_status, latitude, longitude, created_at)
    VALUES ($1, 'PENDING_DISPATCH', $2, $3, GETDATE());

    SET @NewOrderId = SCOPE_IDENTITY();

    -- 2. Fetch serialized JSON string from the session cache
    DECLARE @RawCart NVARCHAR(MAX);
    SELECT @RawCart = cart_json FROM user_sessions WHERE chat_id = $1;

    -- 3. Flatten array elements directly into target relational lines
    INSERT INTO order_items (order_id, item_name, size, quantity, special_instructions)
    SELECT 
        @NewOrderId,
        json_values.item_name,
        json_values.size,
        json_values.quantity,
        json_values.special_instructions
    FROM OPENJSON(@RawCart)
    WITH (
        item_name NVARCHAR(100) '$.item_name',
        size NVARCHAR(20) '$.size',
        quantity INT '$.quantity',
        special_instructions NVARCHAR(255) '$.special_instructions'
    ) AS json_values;

    -- 4. Purge active session cache
    DELETE FROM user_sessions WHERE chat_id = $1;

    COMMIT TRANSACTION;
    SELECT 'SUCCESS' AS transaction_status, @NewOrderId AS order_id;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
